def train(self, rollout_id: int, rollout_data_ref: Box) -> None:
    self._last_rollout_id = rollout_id
    if self.args.offload_train:
        self.wake_up()

    with timer("data_preprocess"):
        rollout_data = get_rollout_data(self.args, rollout_data_ref)
        if self.args.debug_rollout_only:
            log_rollout_data(rollout_id, self.args, rollout_data)
            return

    if self.role == "critic":
        return self.train_critic(rollout_id, rollout_data)
    else:
        return self.train_actor(rollout_id, rollout_data)

def train_critic(self, rollout_id: int, rollout_data: RolloutBatch) -> None:
    # Create data iterator for log_probs and train.
    data_iterator, num_microbatches = get_data_iterator(self.args, self.model, rollout_data)
    rollout_data.update(
        forward_only(
            get_values,
            self.args,
            self.model,
            data_iterator,
            num_microbatches,
        )
    )

    if rollout_id >= self.args.num_critic_only_steps:
        sync_actor_critic_data(self.args, rollout_data, self._actor_critic_groups)

    # --critic-exclude-overlong-penalty: only inside the critic process, swap the GAE reward
    # for the version with the overlong penalty removed (rollout side already computed
    # critic_rewards), so the value-loss regression target (returns) no longer learns length
    # shaping; values/γ/λ (including the gae_lambda_k path) stay identical to the main path.
    # The actor process calls compute_advantages_and_returns separately and never sees this
    # substitution, so advantages are unaffected.
    if getattr(self.args, "critic_exclude_overlong_penalty", False):
        assert "critic_rewards" in rollout_data, (
            "--critic-exclude-overlong-penalty is set but rollout data has no 'critic_rewards'"
        )
        rollout_data["rewards"] = rollout_data["critic_rewards"]
        logger.info("critic exclude shaping: critic returns computed from rewards without overlong penalty")

    compute_advantages_and_returns(self.args, rollout_data)

    self.args.loss_type = "value_loss"
    train(
        rollout_id,
        self.model,
        self.optimizer,
        self.opt_param_scheduler,
        data_iterator,
        num_microbatches,
    )

def _use_rollout_replay(self, m) -> bool:
    return getattr(self.args, f"use_rollout_{m.name}_replay")

def train_actor(self, rollout_id: int, rollout_data: RolloutBatch) -> None:
    print_memory_extended(f"train_actor[{rollout_id}]: entry (after wake_up)", reset_peak=True)

    # Create data iterator for log_probs and train.
    data_iterator, num_microbatches = get_data_iterator(self.args, self.model, rollout_data)

    for m in all_replay_managers:
        if self._use_rollout_replay(m):
            self._fill_replay_data(
                data_iterator,
                num_microbatches,
                rollout_data,
                data_key=m.data_key,
                replay_list=m.replays,
                register_replay_list_func=get_register_replay_list_func(m),
                if_sp_region=m.if_sp_region,
            )

    with inverse_timer("train_wait"), timer("train"):
        if self.args.compute_advantages_and_returns:
            if "ref" in self.weights_backuper.backup_tags:
                self._set_replay_stage("fallthrough")
                self._switch_model("ref")
                print_memory_extended(f"train_actor[{rollout_id}]: before ref_log_probs forward")
                rollout_data.update(
                    self.compute_log_prob(
                        data_iterator,
                        num_microbatches,
                        store_prefix="ref_",
                    )
                )
                print_memory_extended(f"train_actor[{rollout_id}]: after ref_log_probs forward")
            self._switch_model("old_actor" if self.args.keep_old_actor else "actor")
            if not self.args.use_rollout_logprobs or self.args.get_mismatch_metrics or self.args.monitor_logprob_diff:
                for m in all_replay_managers:
                    if m.enabled:
                        if self._use_rollout_replay(m):
                            m.stage = "replay_forward"
                        else:
                            m.stage = "record"
                print_memory_extended(f"train_actor[{rollout_id}]: before actor_log_probs forward")
                rollout_data.update(
                    self.compute_log_prob(
                        data_iterator,
                        num_microbatches,
                        store_prefix="",
                    )
                )

                print_memory_extended(f"train_actor[{rollout_id}]: after actor_log_probs forward")
                for m in all_replay_managers:
                    if self._use_rollout_replay(m):
                        m.clear_all_forward()

            if self.args.use_critic:
                sync_actor_critic_data(
                    self.args,
                    rollout_data,
                    self._actor_critic_groups,
                )
            if self._active_model_tag != "actor":
                self._switch_model("actor")

            # Calculate adv and returns. Need to performed before training (instead of on the fly),
            # because we may need normalize the whole rollout.
            compute_advantages_and_returns(self.args, rollout_data)

        if self.rollout_data_postprocess is not None:
            self.rollout_data_postprocess(self.args)

        log_rollout_data(rollout_id, self.args, rollout_data)

        # Free cached CUDA memory from the log_probs / advantage phases
        # before training to reduce fragmentation pressure.
        clear_memory()

        # Train
        self._set_replay_stage("replay_backward")
        print_memory_extended(f"train_actor[{rollout_id}]: before actor_train (fwd+bwd+optim)", reset_peak=True)
        with timer("actor_train"):
            train(
                rollout_id,
                self.model,
                self.optimizer,
                self.opt_param_scheduler,
                data_iterator,
                num_microbatches,
            )
        print_memory_extended(f"train_actor[{rollout_id}]: after actor_train peak")

        self.prof.step(rollout_id=rollout_id)

    train_dump_utils.save_debug_train_data(self.args, rollout_id=rollout_id, rollout_data=rollout_data)

    for m in all_replay_managers:
        if m.enabled:
            m.clear_all()

    # update the cpu actor weight to the latest model
    self.weights_backuper.backup("actor")

    # Update ref model if needed
    if (
        self.args.ref_update_interval is not None
        and (rollout_id + 1) % self.args.ref_update_interval == 0
        and "ref" in self.weights_backuper.backup_tags
    ):
        with timer("ref_model_update"):
            if is_megatron_main_rank():
                logger.info(f"Updating ref model at rollout_id {rollout_id}")
            self.weights_backuper.backup("ref")

    log_perf_data(rollout_id, self.args)

@timer
def save_model(self, rollout_id: int, force_sync: bool = False) -> None:
    if self.args.debug_rollout_only:
        return

    # During critic-only warmup the actor is not training and its weights are still suspended
    # by the memory saver: saving directly hits a CUDA invalid argument at the dist ckpt
    # all_gather_object, so it must be woken up first (and put back to sleep after the save).
    woke_for_save = False
    if self.args.offload_train and getattr(self, "_asleep", False):
        self.wake_up()
        woke_for_save = True

    # torch dist may trigger nccl communication during saving.
    if self.args.offload_train:
        reload_process_groups()

    if self.args.async_save:
        from megatron.training.async_utils import maybe_finalize_async_save

        maybe_finalize_async_save(blocking=True)

    save(rollout_id, self.model, self.optimizer, self.opt_param_scheduler)

    if force_sync and self.args.async_save:
        maybe_finalize_async_save(blocking=True)

    if self._should_save_hf(rollout_id):
        self._save_hf(rollout_id)

    if self.args.offload_train:
        destroy_process_groups()

    if woke_for_save:
        self.sleep()

def _should_save_hf(self, rollout_id: int) -> bool:
    if self.args.save_hf is None or self.role != "actor":
        return False
    if self.args.save_hf_interval is None:
        return True
    # save_model (and the export inside it) is collective, so this decision
    # must be a pure function of rollout_id and static args: every rank has
    # to reach the same answer or the collectives deadlock.
    return (rollout_id + 1) % self.args.save_hf_interval == 0 or rollout_id == self.args.num_rollout - 1

